\begin{definition}[Open cover]
Let $(X, d)$ be a metric space and $K \subseteq X$. An \emph{open cover} of $K$ is a collection $\{U_\alpha\}_{\alpha \in A}$ of open sets such that $K \subseteq \bigcup_{\alpha \in A} U_\alpha$.
\end{definition}

\begin{definition}[Compact set]
A subset $K$ of a metric space $(X, d)$ is \emph{compact} if every open cover of $K$ has a finite sub-cover.
\end{definition}

\begin{theorem}
Every compact subset of a metric space is closed and bounded.
\end{theorem}

\begin{proof}
Let $K$ be compact in $(X, d)$. Fix $p \in X$ and consider the open cover $\{B(p, n)\}_{n=1}^\infty$ of $K$. By compactness there is a finite sub-cover, so $K \subseteq B(p, N)$ for some $N$; hence $K$ is bounded.

To show $K$ is closed, let $q \notin K$. For each $x \in K$, let $r_x = d(x, q)/2$ and consider the open cover $\{B(x, r_x)\}_{x \in K}$. Extract a finite sub-cover $B(x_1, r_1), \ldots, B(x_n, r_n)$. Then $B(q, \min_i r_i) \cap K = \emptyset$, so $q$ is an interior point of $X \setminus K$. Since $q$ was arbitrary, $X \setminus K$ is open, so $K$ is closed.
\end{proof}

\begin{theorem}[Heine--Borel]
\label{thm:heine-borel}
A subset of $\mathbb{R}^n$ is compact if and only if it is closed and bounded.
\end{theorem}

\begin{lemma}[Bolzano--Weierstrass]
Every bounded sequence in $\mathbb{R}^n$ has a convergent subsequence.
\end{lemma}

\begin{proof}
We argue by repeated bisection. Given a bounded sequence $(x_k)$ in $\mathbb{R}$, it lies in some interval $[a, b]$. At least one of $[a, (a+b)/2]$ or $[(a+b)/2, b]$ contains infinitely many terms; pick that half-interval and a term from it. Repeat. This produces a nested sequence of closed intervals whose lengths tend to zero, and by the nested-intervals theorem their intersection is a single point $\ell$. The subsequence of terms chosen at each step converges to $\ell$.

For $\mathbb{R}^n$, apply the one-dimensional argument to each coordinate in turn (a diagonal argument).
\end{proof}

\begin{theorem}[Extreme value theorem]
\label{thm:evt}
Let $K$ be a non-empty compact subset of a metric space and let $f: K \to \mathbb{R}$ be continuous. Then $f$ attains its maximum and minimum on $K$.
\end{theorem}

\begin{proof}
Since $f$ is continuous and $K$ is compact, $f(K)$ is a compact subset of $\mathbb{R}$ (continuous images of compact sets are compact). By Heine--Borel (Theorem~\ref{thm:heine-borel}), $f(K)$ is closed and bounded. In particular $\sup f(K)$ exists and belongs to $f(K)$ (because $f(K)$ is closed), so the supremum is attained. The argument for the infimum is identical.
\end{proof}

\begin{example}
Show that the set $K = \{(x, y) \in \mathbb{R}^2 : x^2 + y^2 \leq 1\}$ is compact.
\end{example}
